(()=>{'use strict';const $=id=>document.getElementById(id);let machines=[],active=null,gameUrl=null,biosUrl=null,ejsScript=null,scene,renderer,camera,objects=[],last=performance.now(),frames=0;const CDN='https://cdn.emulatorjs.org/stable/data/';function say(t){$('message').textContent=t;$('status').textContent=t.length>22?'ready':'idle'}function initGL(){if(!window.THREE){$('engine').textContent='WebGL unavailable';return}try{const c=$('retroGL');renderer=new THREE.WebGLRenderer({canvas:c,alpha:true,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.setSize(innerWidth,innerHeight);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,.1,200);camera.position.set(0,3,12);scene.add(new THREE.HemisphereLight(0xbfeaff,0x050914,2));const grid=new THREE.GridHelper(100,50,0x164766,0x0b2034);grid.position.y=-3;scene.add(grid);for(let i=0;i<90;i++){const m=new THREE.Mesh(new THREE.BoxGeometry(.08,.08,.08),new THREE.MeshBasicMaterial({color:0x65dfff}));m.position.set((Math.random()-.5)*45,Math.random()*25-5,-Math.random()*80);scene.add(m);objects.push(m)}addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});renderer.setAnimationLoop(t=>{objects.forEach((o,i)=>{o.rotation.x=t*.0002+i*.01;o.rotation.y=t*.0003});renderer.render(scene,camera);frames++;if(t-last>1000){$('fps').textContent=frames+' FPS · GPU scene';frames=0;last=t}})}catch(e){$('engine').textContent='WebGL error';say('WebGL renderer unavailable: '+e.message)}}function renderMachines(){const q=$('filter').value.toLowerCase();$('machineList').innerHTML=machines.filter(m=>(m.title+' '+m.family+' '+m.core).toLowerCase().includes(q)).map(m=>'<button class="machine '+(active?.id===m.id?'active':'')+'" data-id="'+m.id+'">'+m.title+'<small>'+m.family+' · '+m.core+'</small></button>').join('');$('machineList').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>select(machines.find(m=>m.id===b.dataset.id)))}function select(m){if(!m)return;active=m;renderMachines();$('title').textContent=m.title;$('desc').textContent='Browser-native '+m.core+' WebAssembly core with a Three.js WebGL retro workstation shell.';$('family').textContent=m.family;$('core').textContent='core: '+m.core;$('features').textContent=(m.bios?'BIOS/Kickstart may be required · ':'')+'WASM · virtual keyboard · save state';$('game').accept=m.extensions.join(',');say('Ready for '+m.title+'. Choose user-supplied media and boot.')}function stop(){try{window.EJS_emulator?.exit?.()}catch{}if(ejsScript){ejsScript.remove();ejsScript=null}$('emulator').replaceChildren();for(const k of ['EJS_player','EJS_core','EJS_gameUrl','EJS_biosUrl','EJS_pathtodata'])delete window[k];$('status').textContent='stopped'}function boot(){if(!active)return;if(!gameUrl){say('Select user-supplied media first.');return}stop();window.EJS_player='#emulator';window.EJS_core=active.core;window.EJS_gameUrl=gameUrl;window.EJS_pathtodata=CDN;window.EJS_startOnLoaded=true;window.EJS_disableLocalStorage=false;if(biosUrl)window.EJS_biosUrl=biosUrl;ejsScript=document.createElement('script');ejsScript.src=CDN+'loader.js';ejsScript.onload=()=>say(active.title+' emulator loaded.');ejsScript.onerror=()=>say('EmulatorJS loader failed. Check CDN/network access.');document.body.appendChild(ejsScript);say('Loading '+active.title+' core…')}function choose(input,kind){const f=input.files?.[0];if(!f)return;if(kind==='game'){if(gameUrl)URL.revokeObjectURL(gameUrl);gameUrl=URL.createObjectURL(f)}else{if(biosUrl)URL.revokeObjectURL(biosUrl);biosUrl=URL.createObjectURL(f)}say('Selected '+f.name)}function save(){localStorage.setItem('chimera-retro-ui',JSON.stringify({machine:active?.id||null,filter:$('filter').value}));say('UI state saved locally.')}function load(){try{const s=JSON.parse(localStorage.getItem('chimera-retro-ui')||'{}');$('filter').value=s.filter||'';const m=machines.find(x=>x.id===s.machine);if(m)select(m);renderMachines();say('UI state restored.')}catch{say('No saved UI state.')}}$('filter').oninput=renderMachines;$('game').onchange=()=>choose($('game'),'game');$('bios').onchange=()=>choose($('bios'),'bios');$('run').onclick=boot;$('stop').onclick=stop;$('eject').onclick=()=>{if(gameUrl)URL.revokeObjectURL(gameUrl);gameUrl=null;$('game').value='';say('Media ejected.');};$('save').onclick=save;$('load').onclick=load;$('reset').onclick=()=>{localStorage.removeItem('chimera-retro-ui');location.reload()};$('fullscreen').onclick=()=>document.documentElement.requestFullscreen?.();$('home').onclick=()=>location.href='index.html';document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.key;document.dispatchEvent(new KeyboardEvent('keydown',{key:k,bubbles:true}));document.dispatchEvent(new KeyboardEvent('keyup',{key:k,bubbles:true}))});fetch('retro_emulators.json',{cache:'no-store'}).then(r=>r.json()).then(x=>{machines=x.browser_engine?.machines||[];select(machines[0]);renderMachines();load()}).catch(e=>say('Retro emulator manifest failed: '+e.message));initGL()})();